import{_ as r}from"./chunks/Audio.COine8Wh.js";import{_ as a}from"./chunks/Tags.BJ536pW3.js";import{c as n,o,j as i,G as t,ae as s,a as d}from"./chunks/framework.Bw0Gm4PQ.js";const f=JSON.parse('{"title":"Homeland Security and Further Additional Continuing Appropriations Act, 2026.","description":"","frontmatter":{"legisId":"2026-04-30-homeland-security-and-further-additional-continuing-appropriations-act-2026","title":"Homeland Security and Further Additional Continuing Appropriations Act, 2026.","displayTitle":"Homeland Security and Further Additional Continuing Appropriations Act, 2026.","lawNumber":"119-86","billNumber":"H.R. 7147","sourceUrl":"https://www.govinfo.gov/bulkdata/PLAW/119/public/PLAW-119publ86.xml","publishDate":"2026-04-30T00:00:00-05:00","industries":["government-operations","immigration","law-enforcement"],"agencies":["Department of Homeland Security","U.S. Customs and Border Protection","Transportation Security Administration","United States Coast Guard","United States Secret Service","Cybersecurity and Infrastructure Security Agency","Federal Emergency Management Agency","Supreme Court of the United States"],"head":[["script",{"type":"application/ld+json"},"[{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"BreadcrumbList\\",\\"itemListElement\\":[{\\"@type\\":\\"ListItem\\",\\"position\\":1,\\"name\\":\\"Home\\",\\"item\\":\\"https://vladroff.github.io/legis\\"},{\\"position\\":2,\\"@type\\":\\"ListItem\\",\\"name\\":\\"Congress Bills\\",\\"item\\":\\"https://vladroff.github.io/legis/congress-bills\\"},{\\"position\\":3,\\"@type\\":\\"ListItem\\",\\"name\\":\\"Homeland Security and Further Additional Continuing Appropriations Act, 2026.\\",\\"item\\":\\"https://vladroff.github.io/legis/congress-bills/2026-04-30-homeland-security-and-further-additional-continuing-appropriations-act-2026\\"}]},{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"Homeland Security and Further Additional Continuing Appropriations Act, 2026.\\",\\"description\\":\\"Summaries of US legislation.\\",\\"url\\":\\"https://vladroff.github.io/legis/congress-bills/2026-04-30-homeland-security-and-further-additional-continuing-appropriations-act-2026\\",\\"datePublished\\":\\"2026-04-30T00:00:00-05:00\\",\\"dateModified\\":1788887623000,\\"mainEntityOfPage\\":\\"https://vladroff.github.io/legis/congress-bills/2026-04-30-homeland-security-and-further-additional-continuing-appropriations-act-2026\\",\\"author\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"Legis\\"},\\"publisher\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"Legis\\"}}]"]]},"headers":[],"relativePath":"congress-bills/2026-04-30-homeland-security-and-further-additional-continuing-appropriations-act-2026.md","filePath":"congress-bills/2026-04-30-homeland-security-and-further-additional-continuing-appropriations-act-2026.md","lastUpdated":1788887623000}'),l={name:"congress-bills/2026-04-30-homeland-security-and-further-additional-continuing-appropriations-act-2026.md"},h=Object.assign(l,{setup(p){return(c,e)=>(o(),n("div",null,[e[0]||(e[0]=i("h1",{id:"homeland-security-and-further-additional-continuing-appropriations-act-2026",tabindex:"-1"},[d("Homeland Security and Further Additional Continuing Appropriations Act, 2026. "),i("a",{class:"header-anchor",href:"#homeland-security-and-further-additional-continuing-appropriations-act-2026","aria-label":'Permalink to "Homeland Security and Further Additional Continuing Appropriations Act, 2026."'},"​")],-1)),t(r),t(a,{list:"/congress-bills"}),e[1]||(e[1]=s('<p>Signed into law on Thursday, April 30, 2026. Public Law 119-86, H.R. 7147.</p><p><strong>Headline:</strong> The law funds Homeland Security for fiscal 2026 and covers federal operations and personnel costs during a February funding lapse.</p><p><strong>Why it matters:</strong> It keeps border, transportation, cybersecurity, disaster-response, immigration, and protective-security operations funded while providing $26.367 billion for major disasters. It also validates covered spending and personnel payments incurred during the appropriations lapse.</p><p><strong>What the law does:</strong></p><ul><li>Funds the Department of Homeland Security and its major agencies, operations, facilities, grants, training, research, and oversight for fiscal 2026.</li><li>Provides $26.367 billion for major-disaster relief and about $3.837 billion for preparedness, firefighter, nonprofit-security, transit, port, flood-mapping, and emergency food and shelter programs.</li><li>Requires congressional reporting on spending, staffing, acquisitions, awards, pilot programs, disaster reimbursements, migration forecasts, detention, removals, and protective operations.</li><li>Restricts fund transfers and spending on new border-crossing fees, a national identification card, certain intelligence activities, armed long-range drones, and moving Guantanamo detainees into the United States.</li><li>Protects congressional access to immigration detention facilities and strengthens safeguards and record preservation involving pregnancy, infant health, deaths, and alleged abuse in custody.</li><li>Adds targeted funding for immigration-enforcement body cameras, unarmed Coast Guard MQ-9 aircraft, Supreme Court expenses, and a conditional 3.8 percent pay increase for eligible air traffic control personnel.</li><li>Extends temporary federal funding through enactment and treats it as covering the appropriations lapse that began around February 14, 2026.</li><li>Requires available funds to cover federal personnel pay, allowances, and benefits and approves lawful obligations for safety, property protection, orderly shutdowns, and other authorized purposes.</li></ul><p><strong>Who it affects:</strong></p><ul><li>Homeland Security personnel, federal employees affected by the funding lapse, and eligible air traffic control personnel.</li><li>Travelers, border communities, immigrants in federal custody, and people using immigration services.</li><li>State, local, tribal, territorial, nonprofit, transit, port, firefighter, and emergency-management grant recipients.</li><li>Communities recovering from major disasters or relying on preparedness, flood-mapping, food, shelter, cybersecurity, and public-safety programs.</li></ul><p><strong>Practical impact on a regular person:</strong></p><ul><li>Federal homeland security, airport screening, disaster response, cybersecurity, border, immigration, and protective services remain funded.</li><li>Federal workers covered by the law receive required pay and benefits, while disaster-affected communities retain access to major relief and preparedness funding.</li></ul><h2 id="breakdown" tabindex="-1">Breakdown <a class="header-anchor" href="#breakdown" aria-label="Permalink to &quot;Breakdown&quot;">​</a></h2><h3 id="division-a-department-of-homeland-security-appropriations-act-2026" tabindex="-1">DIVISION A, DEPARTMENT OF HOMELAND SECURITY APPROPRIATIONS ACT, 2026 <a class="header-anchor" href="#division-a-department-of-homeland-security-appropriations-act-2026" aria-label="Permalink to &quot;DIVISION A, DEPARTMENT OF HOMELAND SECURITY APPROPRIATIONS ACT, 2026&quot;">​</a></h3><p>This division funds the Department of Homeland Security and its major agencies for fiscal year 2026, including border and transportation security, the Coast Guard, the Secret Service, cybersecurity, disaster response, immigration services, training, research, and departmental oversight. It also funds major preparedness and security grants, provides $26.367 billion for major-disaster relief, and sets detailed rules for spending, reporting, detention practices, acquisitions, and congressional oversight. Additional funding supports body-worn cameras, Coast Guard unmanned aircraft, Supreme Court operations, and a potential pay increase for air traffic controllers.</p><p><strong>Key takeaways:</strong></p><ul><li>The division provides operating and capital funding for Customs and Border Protection, the Transportation Security Administration, the Coast Guard, the Secret Service, the Cybersecurity and Infrastructure Security Agency, the Federal Emergency Management Agency, and other Homeland Security offices.</li><li>It provides $26.367 billion for major-disaster relief and about $3.837 billion for preparedness, firefighter, nonprofit security, transit, port, flood-mapping, emergency food and shelter, and related grants and programs.</li><li>It requires extensive reporting to Congress on spending, staffing, major acquisitions, noncompetitive awards, pilot programs, disaster reimbursements, border migration forecasts, detention and removal forecasts, and certain protective operations.</li><li>It restricts the movement of funds without advance notice to Congress and limits spending on activities including new border crossing fees, a national identification card, certain intelligence activities, armed long-range unmanned aircraft, and transfers of Guantanamo detainees into the United States.</li><li>It protects congressional access to immigration detention facilities, limits restraints on pregnant or postpartum women in Homeland Security custody, requires preservation of records concerning deaths and alleged abuse in custody, and maintains health safeguards for pregnant women and infants in Customs and Border Protection custody.</li><li>It provides targeted additional funding for immigration-enforcement body cameras, Coast Guard MQ-9 aircraft without kinetic capabilities, Supreme Court expenses, and a conditional 3.8 percent pay increase for eligible air traffic control personnel.</li></ul><h3 id="division-b-further-additional-continuing-appropriations-act-2026" tabindex="-1">DIVISION B, FURTHER ADDITIONAL CONTINUING APPROPRIATIONS ACT, 2026 <a class="header-anchor" href="#division-b-further-additional-continuing-appropriations-act-2026" aria-label="Permalink to &quot;DIVISION B, FURTHER ADDITIONAL CONTINUING APPROPRIATIONS ACT, 2026&quot;">​</a></h3><p>This division extends the Continuing Appropriations Act, 2026, through the date this law is enacted and treats its funding coverage as including the appropriations lapse that began around February 14, 2026. It also requires covered personnel payments and approves otherwise lawful obligations incurred to protect life and property, shut down government operations in an orderly way, or carry out other authorized purposes.</p><p><strong>Key takeaways:</strong></p><ul><li>Temporary federal funding is extended through the enactment date of this law.</li><li>The funding period is treated as covering the appropriations lapse that began around February 14, 2026.</li><li>Available funds must be used to make required payments for federal personnel pay, allowances, and benefits.</li><li>Otherwise lawful obligations incurred to protect life and property, support an orderly shutdown, or carry out other authorized purposes are approved.</li><li>The division may be cited as the Further Additional Continuing Appropriations Act, 2026.</li></ul><p>Source: <a href="https://www.govinfo.gov/bulkdata/PLAW/119/public/PLAW-119publ86.xml" target="_blank" rel="noreferrer">https://www.govinfo.gov/bulkdata/PLAW/119/public/PLAW-119publ86.xml</a></p>',19))]))}});export{f as __pageData,h as default};
